TERMINATION_BENEFIT.eligibility:
const employment = ctx.subject.employment;
const terms = employment.terms;
const months = calendar_completed_months(
	get(employment, 'service_started_on', employment.effective_range.from),
	add_days(ctx.entry.incurred_on, 1)
);
if (!(ctx.entry.quantity > 0)) return false;
const exit = get(employment, 'effective_range.to', null);
if (exit !== null && !(ctx.entry.incurred_on <= exit)) return false;
if (!(months >= ctx.lookup.service_months)) return false;
const facts = get(employment, 'statutory_parameters', {});
const ground = get(employment, 'exit_ground', get(facts, 'exit_ground', ''));
if (['RESIGNATION', 'RETIREMENT', 'EMPLOYEE_RETIREMENT', 'MISCONDUCT_DISMISSAL', 'TRANSFER', 'TRANSFER_TO_SUBSIDIARY'].includes(ground)) return false;
if (get(facts, 'misconduct_dismissal', false) === true) return false;
const monthly = Number(ctx.month_wage);
// First Schedule para 2(5): Part XIIA does not reach a domestic employee.
const category = get(terms, 'statutory_work_category', '');
if (category === 'DOMESTIC') return false;
if (monthly <= ctx.lookup.monthly_wage_threshold) return true;
return ctx.lookup.manual_categories.includes(category);

TERMINATION_BENEFIT.conversion:
const employment = ctx.subject.employment;
const started = get(employment, 'service_started_on', employment.effective_range.from);
const ended = ctx.entry.incurred_on;
const completed = calendar_completed_months(started, add_days(ended, 1));
// Reg.6(1): the band is the completed service; a part year counts pro rata to the nearest month.
const anniversary = add_months(started, completed);
const remainder = calendar_distance_days(anniversary, ended);
const span = calendar_distance_days(anniversary, add_months(started, completed + 1));
const months = completed + (remainder * 2 >= span ? 1 : 0);
const days =
	completed < ctx.lookup.first_band_months ? ctx.lookup.first_band_days
	: completed < ctx.lookup.second_band_months ? ctx.lookup.second_band_days
	: ctx.lookup.third_band_days;
// Reg.6(2), JTKSM formula: a day's wages is twelve months' wages over 365. The floor uses the contract month with its
// fixed allowances (any rate unit); HR enters the amount from the actual twelve months' wages where it is higher.
const dayWage = (ctx.month_wage * 12) / ctx.lookup.year_days;
return Math.max(ctx.entry.quantity, dayWage * days * (months / 12));

