REST_DAY_OVERTIME.conversion:
const employment = ctx.subject.employment;
const terms = employment.terms;
const facts = get(employment, 'statutory_parameters', {});
const partTime = get(employment, 'engagement', 'EMPLOYEE') === 'PART_TIME';
const normal = Number(
	get(
		terms,
		'normal_hours_per_day',
		partTime
			? ctx.lookup.part_time_hours_factor * 8
			: 8
	)
);
const full = partTime
	? Number(
			get(facts, 'comparable_full_time_hours_per_day', 8)
		)
	: normal;
const tier = Math.max(0, full - normal);
const orpHour = ctx.hour_rate;
const days = get(ctx, 'work.days', []);
// Every holiday kind except MAKEUP_WORKDAY earns the premium; a makeup workday is a plain working day.
const holiday = (day) => {
	const kind = get(day, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
// EA ss.7, 7A: the employer's rest-day hourly multiple stands on each day it pays more than s.60(3)(c).
const multiple = Number(get(ctx.subject.employer, 'pay_methods.rest_day_hourly_multiplier', 0));
const charged = sum(
	days
		.filter((day) => get(day, 'day_type', 'WORK') === 'REST' && !holiday(day))
		.map((day) => {
			const worked = Math.max(0, Number(get(day, 'worked_hours', 0)) - normal);
			const owed = partTime
				? Math.min(worked, tier) * ctx.lookup.part_time_premium +
						Math.max(0, worked - tier) * ctx.lookup.rest_day_premium
				: worked * ctx.lookup.rest_day_premium;
			return Math.max(owed, worked * multiple);
		})
);
return charged * orpHour;

