EPF.employee_amount:
// EPF Act 1991 s.2, 3rd Sch. Part A/E: includes contractual incentives; excl. overtime/rest-day/PH work; >RM20k or bonus-crossing RM5k rounds each share UP to RM1.
const employment = ctx.subject.employment;
const month = get(ctx, 'balances.month', {});
const paidMonth = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.from)).slice(0, 7);
const heldIn = (code) => (Object.hasOwn(month, paidMonth + '.' + code) ? Number(month[paidMonth + '.' + code]) : 0);
const coverage = ctx.run.salary_coverage;
const wholeMonth = String(coverage.from) === String(month_start(coverage.from)) && String(coverage.to) === String(month_end(coverage.from));
const separate = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn('BASIC') > 0;
const before = (code) => (separate ? 0 : heldIn(code));
const under = get(ctx.run, 'kind', '') === 'OFF_CYCLE' && before('AWARDS') === 0 ? ctx.month_wage : 0;
const epfExtra = ctx.subtotals.INCENTIVE_OT + before('INCENTIVE_OT') - ctx.subtotals.LONG_SERVICE - before('LONG_SERVICE');
const paid = Math.max(0, ctx.subtotals.ADDITIONAL_WAGES + before('ADDITIONAL_WAGES') - ctx.subtotals.ORDINARY_WAGES - before('ORDINARY_WAGES') + ctx.subtotals.AWARDS + before('AWARDS') + epfExtra);
const dob = get(employment, 'payroll.date_of_birth', '');
const age = age_on(dob, add_days(month_start(ctx.run.salary_coverage.from), -1));
const volRate = Number(get(employment, 'statutory_parameters.statutory.EPF.employee_rate', 0));
const owed = (w) => {
	if (age >= ctx.lookup.senior_age || w <= ctx.lookup.minimum_chargeable) return 0;
	if (w > ctx.lookup.table_ceiling) {
		const statutory = round(w * ctx.lookup.employee_rate, ctx.lookup.whole_unit, 'UP');
		return Math.max(statutory, round(w * volRate, ctx.lookup.whole_unit, 'UP'));
	}
	const band = w <= ctx.lookup.lower_rate_ceiling ? round(w, ctx.lookup.lower_salary_step, 'UP') : round(w, ctx.lookup.hundred_units, 'UP');
	const statutory = round(band * ctx.lookup.employee_rate, ctx.lookup.whole_unit, 'UP');
	return Math.max(statutory, round(w * volRate, ctx.lookup.whole_unit, 'UP'));
};
return owed(paid + under) - owed(under) - before('EPF.employee');

