	String(coverage.from) === String(month_start(coverage.from)) && String(coverage.to) === String(month_end(coverage.from));
const separate = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn('BASIC') > 0;
const before = (code) => (separate ? 0 : heldIn(code));
// s.2: overtime and gratuity sit between AWARDS and ORDINARY_WAGES; pay for work on a rest day or a public holiday is an overtime payment and sits there too.
// An incentive is remuneration under the contract, not an overtime payment: its step counts.
const paid = Math.max(
	0,
	ctx.subtotals.ADDITIONAL_WAGES + before('ADDITIONAL_WAGES') - ctx.subtotals.ORDINARY_WAGES - before('ORDINARY_WAGES') + ctx.subtotals.AWARDS + before('AWARDS') +
		ctx.subtotals.INCENTIVE_OT + before('INCENTIVE_OT') - ctx.subtotals.LONG_SERVICE - before('LONG_SERVICE')
);
// KWSP's published method (FAQ): each share rounds up to the next ringgit; it pays more than Part F para 2's rounding of the total.
return round(paid * ctx.lookup.employee_rate, ctx.lookup.whole_unit, 'UP') - before('EPF_NON_CITIZEN.employee');

