SOCSO.employee_amount:
// Employees’ Social Security Act 1969 (Act 4) s.2(5); First Schedule paras 12(i)-(iii), 12(iv), 12A; Third Schedule: employee statutory calculation.
const employment = ctx.subject.employment;
const dob = get(employment, 'payroll.date_of_birth', '');
const age = age_on(dob, add_days(month_start(ctx.run.salary_coverage.from), -1));
if (age >= ctx.lookup.senior_age) return 0;
if (get(employment, 'statutory_parameters.receiving_pension', false) === true) return 0;
if (age >= ctx.lookup.new_entrant_senior_age && get(employment, 'statutory_parameters.statutory.SOCSO.first_insured_at_55_or_more', false) === true) return 0;
const month = get(ctx, 'balances.month', {});
const paidMonth = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.from)).slice(0, 7);
const heldIn = (code) => (Object.hasOwn(month, paidMonth + '.' + code) ? Number(month[paidMonth + '.' + code]) : 0);
const coverage = ctx.run.salary_coverage;
const wholeMonth =
	String(coverage.from) === String(month_start(coverage.from)) && String(coverage.to) === String(month_end(coverage.from));
const separate = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn('BASIC') > 0;
const before = (code) => (separate ? 0 : heldIn(code));
const charge = (w) => {
if (w <= 0) return 0;
if (w <= ctx.lookup.salary_class_step) return bracket(w, ctx.lookup.employee_bands);
const midpoint = w >= ctx.lookup.salary_ceiling ? ctx.lookup.highest_midpoint : round(w, ctx.lookup.hundred_units, 'UP') - ctx.lookup.midpoint_offset;
return midpoint * ctx.lookup.employee_rate;
};
return charge(Math.min(ctx.subtotals.ORDINARY_WAGES + before('ORDINARY_WAGES'), ctx.lookup.salary_ceiling)) - before('SOCSO.employee');

SOCSO.employer_amount:
// Employees’ Social Security Act 1969 (Act 4) s.2(5); First Schedule paras 12(i)-(iii), 12(iv), 12A; Third Schedule: employer statutory calculation.
const employment = ctx.subject.employment;
const dob = get(employment, 'payroll.date_of_birth', '');
const age = age_on(dob, add_days(month_start(ctx.run.salary_coverage.from), -1));
