const heldIn = (code) => (Object.hasOwn(month, paidMonth + '.' + code) ? Number(month[paidMonth + '.' + code]) : 0);
const coverage = ctx.run.salary_coverage;
const wholeMonth =
	String(coverage.from) === String(month_start(coverage.from)) && String(coverage.to) === String(month_end(coverage.from));
const separate = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn('BASIC') > 0;
const before = (code) => (separate ? 0 : heldIn(code));
const charge = (w) => {
if (w <= 0) return 0;
const lateEntrant = age >= ctx.lookup.new_entrant_senior_age && get(employment, 'statutory_parameters.statutory.SOCSO.first_insured_at_55_or_more', false) === true;
const invalid = get(employment, 'statutory_parameters.receiving_pension', false) === true;
const employerOnly = age >= ctx.lookup.senior_age || lateEntrant || invalid;
if (employerOnly) {
 if (w <= ctx.lookup.salary_class_step) return bracket(w, ctx.lookup.senior_bands);
 const midpoint = w >= ctx.lookup.salary_ceiling ? ctx.lookup.highest_midpoint : round(w, ctx.lookup.hundred_units, 'UP') - ctx.lookup.midpoint_offset;
 return round(midpoint * ctx.lookup.employer_only_rate, ctx.lookup.half_step, 'HALF_EVEN');
}
if (w <= ctx.lookup.salary_class_step) return bracket(w, ctx.lookup.employer_bands);
const midpoint = w >= ctx.lookup.salary_ceiling ? ctx.lookup.highest_midpoint : round(w, ctx.lookup.hundred_units, 'UP') - ctx.lookup.midpoint_offset;
return round(midpoint * ctx.lookup.employer_rate, ctx.lookup.table_step, 'DOWN') + ctx.lookup.half_step;
};
return Math.max(0, charge(Math.min(ctx.subtotals.ORDINARY_WAGES + before('ORDINARY_WAGES'), ctx.lookup.salary_ceiling)) - before('SOCSO.employer'));

